// update__App runs App's update for msg and answers its Nav: Redirect p is a 303 to p; Rerender and
// Reject t are a 303 back to the page that sent the message (the Referer, else /), as App has no
// page of its own to render (a Reject's text is not shown). The session the Task leaves is stored;
// a failed Task changes nothing: 500 (App.error), or 404 for Query.notFound or Task.notFound.
func update__App(rq *web.Request, msg App__Msg) web.Response {
	nav, err := eff.Run(rq.Env, eff.KTask, App__update(msg, rq.Env.Session.(App__Session)))
	if err != nil {
		return route__fail(err)
	}
	nav, rq.Notice = nav.Unnotice()
	if nav.Tag == rt.NavRedirect {
		return web.RedirectResponse(rt.PageURL(nav.Page), rq.Env.Session)
	}
	return web.RedirectResponse(rt.BackURL(rq.HTTP.Referer()), rq.Env.Session)
}

// Route__App__Leave serves App's message Leave, POST /_m/App/Leave: update__App.
func Route__App__Leave() web.Route {
	return web.Route{Method: "POST", Pattern: "/_m/App/Leave", Handle: func(rq *web.Request) web.Response {
		return update__App(rq, App__Msg__Leave__)
	}}
}

// encode__Projects__Index__NewProject is form NewProject as the browser's inputs submit it, for
// Test.submit (test builds): the inverse of decode__Projects__Index__NewProject.
func encode__Projects__Index__NewProject(r Projects__Index__NewProject) rtesting.Fields {
	v := url.Values{}
	var absent []string
	v.Set("name", r.Name)
	return rtesting.Fields{Values: v, Absent: absent}
}

// route__fail answers a load or update that did not succeed: 404 (App.notFound) for
// Query.notFound and Task.notFound, 503 (App.maintenance) for a silo that is not served, else
// 500 (App.error).
func route__fail(err error) web.Response {
	if errors.Is(err, eff.ErrNotFound) {
		return web.NotFoundResponse(html.None())
	}
	var m *db.MaintenanceError
	if errors.As(err, &m) {
		return web.MaintenanceResponse(err)
	}
	return web.ErrorResponse(html.None(), err)
}

// route__values are the submitted fields of a form as its re-render shows them: the first value
// of each field, without the Text.Secret fields named in secrets.
func route__values(v url.Values, secrets ...string) map[string]string {
	out := map[string]string{}
	for k, vs := range v {
		if len(vs) > 0 {
			out[k] = vs[0]
		}
	}
	for _, s := range secrets {
		delete(out, s)
	}
	return out
}

// route__errors are a form's decoding errors by field, for html.FormState.
func route__errors(errs []web.FieldError) map[string][]string {
	out := map[string][]string{}
	for _, e := range errs {
		out[e.Field] = append(out[e.Field], e.Message)
	}
	return out
}
